import { FC, HTMLAttributes } from 'react';

import { theme } from 'antd';
import cn from 'classnames';

import styles from './Page.module.scss';

interface IPageProps extends HTMLAttributes<HTMLDivElement> {
	withoutHeading?: boolean;
}

export const Page: FC<IPageProps> = ({ className, children, withoutHeading, ...props }) => {
	const {
		token: { colorBgBase },
	} = theme.useToken();

	return (
		<div
			{...props}
			style={{ background: colorBgBase }}
			className={cn(className, styles.page, withoutHeading && styles.page_withoutHeading)}>
			{children}
		</div>
	);
};
